// 由 dev/common/sculpt_skull.py 离线融合的鹿头骨网格：开放眼眶、颧弓和鼻骨保留真实深度。
import * as THREE from 'three';
const decode=s=>{const raw=atob(s),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a.buffer;};
const low=[-0.13950003683567047, -0.2483338713645935, 0.012808377854526043],span=[0.278995543718338, 0.5077376961708069, 0.18548961449414492];
let cached;
export function sculptedDeerGeometry(){
 if(cached)return cached;
 const p=new Uint16Array(decode('')),n=new Int8Array(decode('')),positions=new Float32Array(p.length),normals=new Float32Array(n.length);
 for(let i=0;i<p.length;i++){positions[i]=low[i%3]+p[i]/65535*span[i%3];normals[i]=n[i]/127;}
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(positions,3));g.setAttribute('normal',new THREE.BufferAttribute(normals,3));g.setIndex(new THREE.BufferAttribute(new Uint16Array(decode('')),1));cached=g;return g;
}
